//! The wire types of `proto/rastai/`, generated by prost (layout: rust-node-gateway-proto.md section 3.4).
//!
//! This is the one hand-written file of the crate. Each proto package `rastai.<package>.v1` is the module
//! `rastai_proto::<package>::v1`, and its body is the generated file `src/generated/rastai.<package>.v1.rs`, which
//! `just codegen` writes and nobody edits. prost refers to another package's types by relative paths
//! (`super::super::common::v1::Diagnostic`), so this tree must mirror the package names exactly.

pub mod common {
    pub mod v1 {
        include!("generated/rastai.common.v1.rs");
    }
}

pub mod commands {
    pub mod v1 {
        include!("generated/rastai.commands.v1.rs");
    }
}

pub mod events {
    pub mod v1 {
        include!("generated/rastai.events.v1.rs");
    }
}
